import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    # 双指针：当前可用的最小和最大
    L, R = 1, n
    ans = []

    for _ in range(n):
        # 若把 R 放在当前位置，可贡献 (R - L) 个逆序对
        if k >= (R - L):
            ans.append(R)   # 放最大值，尽量买满这一位能买到的逆序对
            k -= (R - L)
            R -= 1
        else:
            ans.append(L)   # 放最小值，本步不增加逆序对
            L += 1

    print(' '.join(map(str, ans)))

