import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    L = 1           # 当前剩余的最小数字
    R = n           # 当前剩余的最大数字
    ans = []

    for _ in range(n):
        # 如果放 R 可以产生的错位数 (R - L) 不超过剩余的 k，则放 R
        if k >= (R - L):
            ans.append(R)
            k -= (R - L)   # 用掉这些错位
            R -= 1
        else:
            ans.append(L)   # 放 L 不产生新的错位
            L += 1

    print(' '.join(map(str, ans)))

if __name__ == "__main__":
    main()
